110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        String address = normalizeAddress(owner.getAddress());
115	        if (address.isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
117	        }
118	        owner.setAddress(address);
119	        if (owner.getEmail() != null) {
120	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
121	            if (!EMAIL_PATTERN.matcher(email).matches()) {
122	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	            }
124	            owner.setEmail(email);
125	        }
126	        String telephone = normalizeTelephone(owner.getTelephone());
127	        if (telephone == null) {
128	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
129	        }
130	        owner.setTelephone(telephone);
131	        if (owner.getRegistrationDate() == null) {
132	            owner.setRegistrationDate(LocalDate.now());
133	        }
134	        if (isTelephoneInUse(telephone)) {
135	            return new ResponseEntity<>(HttpStatus.CONFLICT);
136	        }
137	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && isHouseholdInUse(owner)) {
138	            return new ResponseEntity<>(HttpStatus.CONFLICT);
139	        }
140	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
141	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
142	        owner.setHouseholdId(householdId(owner));
143	        owner.setNamesakeCount(countNamesakes(owner));
144	        this.clinicService.saveOwner(owner);
145	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
