317	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
318	     * last name, compared case-insensitively.
319	     */
320	    private int countNamesakes(Owner owner) {
321	        String firstName = normalizeHouseholdField(owner.getFirstName());
322	        String lastName = normalizeHouseholdField(owner.getLastName());
323	        return (int) this.clinicService.findAllOwners().stream()
