343	    /**
344	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
345	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
346	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
347	     * string when {@code address} is null or blank after normalization.
348	     */
349	    private static String normalizeAddress(String address) {
350	        if (address == null) {
351	            return "";
352	        }
353	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
354	        if (collapsed.isEmpty()) {
355	            return "";
356	        }
357	        StringBuilder sb = new StringBuilder(collapsed.length());
358	        for (String token : collapsed.split(" ")) {
359	            if (sb.length() > 0) {
360	                sb.append(' ');
361	            }
362	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
