383	        String lastName = normalizeHouseholdField(owner.getLastName());
384	        String address = normalizeHouseholdField(owner.getAddress());
385	        return this.clinicService.findAllOwners().stream()
386	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
