401	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
402	     * deterministically from those normalized fields so housemates always resolve to the same value,
403	     * regardless of registration order.
404	     */
405	    private static String householdId(Owner owner) {
406	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
407	            + normalizeHouseholdField(owner.getAddress());
408	        try {
409	            byte[] digest = MessageDigest.getInstance("SHA-256")
410	                .digest(key.getBytes(StandardCharsets.UTF_8));
411	            StringBuilder sb = new StringBuilder(24);
412	            for (int i = 0; i < 12; i++) {
413	                sb.append(String.format("%02X", digest[i]));
414	            }
415	            return sb.toString();
416	        }
417	        catch (NoSuchAlgorithmException e) {
418	            throw new IllegalStateException("SHA-256 not available", e);
419	        }
